import { Order } from '../domain/Order';
import { OrderItem } from '../domain/OrderItem';
import { OrderRepository } from '../domain/OrderRepository';
import { ProductRepository } from '../domain/ProductRepository';
import { Quantity } from '../domain/Quantity';
import { CreateOrderRequest } from './dto/CreateOrderRequest';

export class PlaceOrderUseCase {
  constructor(
    private orderRepository: OrderRepository,
    private productRepository: ProductRepository,
  ) {}

  execute(request: CreateOrderRequest): string {
    const items: OrderItem[] = [];

    for (const item of request.items) {
      const product = this.productRepository.findById(item.productId);
      if (!product) {
        throw new Error(`Product ${item.productId} not found`);
      }

      const quantity = Quantity.create(item.quantity);
      product.reserveStock(quantity);
      items.push(OrderItem.create(item.productId, quantity));
    }

    const orderId = this.generateOrderId();
    const order = Order.create(orderId, items);
    this.orderRepository.save(order);

    return orderId;
  }

  private generateOrderId(): string {
    return `ORD-${Date.now()}-${Math.random().toString(36).substr(2, 9)}`;
  }
}

